function getAcademyPerformanceCheckpoint(chapter) {
  if (!Number.isInteger(chapter)) return null;
  const questions = specs3[chapter];
  if (!questions) return null;
  return questions.map((question, index) => ({
    id: `chapter-${chapter}-performance-checkpoint-v1-${index + 1}`,
    kind: "single",
    question: question.prompt,
    options: [...question.options],
    correctIndex: question.correct,
    competencyId: `ch${chapter}-${question.objective}`,
    difficulty: question.safety ? 3 : 2,
    explanation: question.why,
    remediationCardIds: [`ch${chapter}-${question.section}`],
    ...question.safety ? { mustPass: true } : {}
  }));
}

