    { objective: "stage", section: "life-map", prompt: "Hai ng\u01B0\u1EDDi c\xF9ng 45 tu\u1ED5i, m\u1ED9t c\u1EA7n h\u1EADu c\u1EA7n b\u1EEFa, m\u1ED9t c\xF3 tri\u1EC7u ch\u1EE9ng v\xE0 h\u01B0\u1EDBng d\u1EABn ch\u0103m s\xF3c ri\xEAng. \u0110i\u1EC3m b\u1EAFt \u0111\u1EA7u?", options: ["H\u1ECFi b\u1ED1i c\u1EA3nh v\xE0 \u01B0u ti\xEAn \u0111\u01B0\u1EE3c \u0111\u1ED3ng \xFD c\u1EE7a t\u1EEBng ng\u01B0\u1EDDi, kh\xF4ng c\xF9ng m\u1ED9t menu theo tu\u1ED5i.", "Sao th\u1EF1c \u0111\u01A1n theo tu\u1ED5i cho c\u1EA3 hai.", "Suy c\u1EA3 hai c\xF9ng giai \u0111o\u1EA1n hormone.", "Y\xEAu c\u1EA7u to\xE0n b\u1ED9 l\u1ECBch sinh s\u1EA3n m\u1EDBi \u0111\u01B0\u1EE3c h\u1ECDc."], correct: 0, why: "Tu\u1ED5i kh\xF4ng x\xE1c \u0111\u1ECBnh giai \u0111o\u1EA1n, \u0111i\u1EC1u tr\u1ECB ho\u1EB7c ngu\u1ED3n l\u1EF1c. C\xE2u h\u1ECFi t\u1ED1i thi\u1EC3u ph\u1EA3i ph\u1EE5c v\u1EE5 m\u1EE5c ti\xEAu v\xE0 quy\u1EC1n ri\xEAng t\u01B0." },
    { objective: "stage", section: "life-map", prompt: "Thi\u1EBFu ni\xEAn g\u1EA7n b\u1EB1ng chi\u1EC1u cao ng\u01B0\u1EDDi l\u1EDBn c\xF3 th\u1EC3 d\xF9ng b\u1EA3ng gi\u1EA3m calorie c\u1EE7a ng\u01B0\u1EDDi \u0111\xF3 kh\xF4ng?", options: ["C\xF3 v\xEC chi\u1EC1u cao l\xE0 \u0111\u1EE7.", "C\xF3 n\u1EBFu c\xE2n c\u0169ng g\u1EA7n b\u1EB1ng.", "Kh\xF4ng; t\u0103ng tr\u01B0\u1EDFng l\xE0 b\u1ED1i c\u1EA3nh kh\xE1c, c\u1EA7n h\u01B0\u1EDBng d\u1EABn ph\xF9 h\u1EE3p l\u1EE9a tu\u1ED5i thay v\xEC sao k\u1EBF ho\u1EA1ch ng\u01B0\u1EDDi l\u1EDBn.", "C\xF3 n\u1EBFu th\u1EDDi gian ng\u1EAFn."], correct: 2, why: "Ch\u01B0\u01A1ng n\xE0y kh\xF4ng k\xEA ch\u1EBF \u0111\u1ED9 cho tr\u1EBB; \u0111\u1EB7c \u0111i\u1EC3m gi\u1ED1ng nhau kh\xF4ng cho ph\xE9p chuy\u1EC3n m\u1ED9t k\u1EBF ho\u1EA1ch ng\u01B0\u1EDDi l\u1EDBn.", safety: true },
    { objective: "nutrients", section: "folate-label", prompt: "A ghi 340 mcg DFE (200 mcg folic acid), B 100 mcg folic acid. M\u1ED9t kh\u1EA9u ph\u1EA7n m\u1ED7i lo\u1EA1i c\xF3 t\u1ED5ng folic acid?", options: ["640 mcg.", "300 mcg = 0,3 mg, ch\u01B0a k\u1EBFt lu\u1EADn n\xEAn ph\u1ED1i s\u1EA3n ph\u1EA9m.", "440 mcg v\xE0 lu\xF4n an to\xE0n.", "0,3 mcg."], correct: 1, why: "C\u1ED9ng c\xF9ng d\u1EA1ng 200 + 100 = 300 mcg. Kh\xF4ng c\u1ED9ng DFE v\u1EDBi folic acid nh\u01B0 hai th\xE0nh ph\u1EA7n; ki\u1EC3m k\xEA kh\xF4ng k\xEA li\u1EC1u." },
    { objective: "nutrients", section: "folate-label", prompt: "Tham chi\u1EBFu CDC 400 mcg folic acid c\xF3 x\xE1c \u0111\u1ECBnh li\u1EC1u cho m\u1ECDi ng\u01B0\u1EDDi c\xF3 y\u1EBFu t\u1ED1 nguy c\u01A1 ho\u1EB7c thu\u1ED1c kh\xF4ng?", options: ["C\xF3, m\u1ECDi ho\xE0n c\u1EA3nh nh\u01B0 nhau.", "C\xF3, ch\u1EC9 c\u1EA7n th\xEAm s\u1EA3n ph\u1EA9m kh\xE1c.", "C\xF3, v\xEC DFE lu\xF4n b\u1EB1ng folic acid.", "Kh\xF4ng; tham chi\u1EBFu c\xF3 ph\u1EA1m vi, c\u1EA7n trao \u0111\u1ED5i ng\u01B0\u1EDDi ch\u0103m s\xF3c v\xE0 kh\xF4ng t\u1EF1 ch\u1ECDn li\u1EC1u cao hay ng\u1EEBng thu\u1ED1c."], correct: 3, why: "T\xE1ch h\u01B0\u1EDBng d\u1EABn d\xE2n s\u1ED1 kh\u1ECFi ch\u1EC9 \u0111\u1ECBnh c\xE1 nh\xE2n, nh\u1EA5t l\xE0 khi c\xF3 b\u1EC7nh, ti\u1EC1n s\u1EED ho\u1EB7c thu\u1ED1c li\xEAn quan." },
    { objective: "coordination", section: "pregnancy-postpartum", prompt: "Ca gi\u1EA3 \u0111\u1ECBnh m\u01B0\u1EDDi tu\u1EA7n sau sinh c\xF3 \u0111au ng\u1EF1c v\xE0 kh\xF3 th\u1EDF. B\u01B0\u1EDBc \u0111\u1EA7u?", options: ["T\xECm tr\u1EE3 gi\xFAp kh\u1EA9n c\u1EA5p t\u1EA1i \u0111\u1ECBa ph\u01B0\u01A1ng v\xE0 n\xF3i r\xF5 sau sinh, kh\xF4ng ch\u1EDD coach.", "Ch\u1EDD \u0111\u1EE7 nh\u1EADt k\xFD b\u1EA3y ng\xE0y.", "T\u1EF1 t\u0103ng s\u1EA3n ph\u1EA9m n\u0103ng l\u01B0\u1EE3ng.", "Kh\xF4ng c\u1EA7n quan t\xE2m v\xEC qua s\xE1u tu\u1EA7n."], correct: 0, why: "D\u1EA5u hi\u1EC7u \u0111\xE1ng lo c\xF3 th\u1EC3 xu\u1EA5t hi\u1EC7n ngo\xE0i m\u1ED1c s\xE1u tu\u1EA7n; kh\xF4ng tr\xEC ho\xE3n ch\u0103m s\xF3c \u0111\u1EC3 t\u1EF1 gi\u1EA3i th\xEDch b\u1EB1ng b\u1EEFa ho\u1EB7c thi\u1EBFu ng\u1EE7.", safety: true },
    { objective: "coordination", section: "pregnancy-postpartum", prompt: "Ng\u01B0\u1EDDi cho con b\xFA \u0111\u1ECBnh lo\u1EA1i nhi\u1EC1u nh\xF3m th\u1EE9c \u0103n \u0111\u1EC3 t\u1EF1 ch\u1EA9n \u0111o\xE1n tri\u1EC7u ch\u1EE9ng c\u1EE7a b\xE9. C\xE1ch ph\xF9 h\u1EE3p?", options: ["Lo\u1EA1i c\xE0ng nhi\u1EC1u c\xE0ng nhanh.", "D\xF9ng l\u1EDDi k\u1EC3 tr\xEAn m\u1EA1ng thay \u0111\xE1nh gi\xE1.", "Ph\u1ED1i h\u1EE3p ng\u01B0\u1EDDi ch\u0103m s\xF3c m\u1EB9 v\xE0 b\xE9, kh\xF4ng t\u1EF1 d\xF9ng lo\u1EA1i tr\u1EEB r\u1ED9ng \u0111\u1EC3 ch\u1EA9n \u0111o\xE1n.", "Ch\u1EC9 d\u1EF1a m\u1ED9t b\u1EEFa \u0111\u1EC3 x\xE1c \u0111\u1ECBnh d\u1ECB \u1EE9ng."], correct: 2, why: "C\u1EA7n \u0111\xE1nh gi\xE1 b\u1ED1i c\u1EA3nh m\u1EB9 v\xE0 b\xE9; kh\xF4ng t\u1EF1 thu h\u1EB9p \u0103n ho\u1EB7c g\xE1n quan h\u1EC7 nh\xE2n qu\u1EA3 t\u1EEB quan s\xE1t ng\u1EAFn.", safety: true },
    { objective: "privacy", section: "private-passport", prompt: "H\u1ECDc vi\xEAn ch\u1ECDn kh\xF4ng khai chu k\u1EF3 th\u1EADt. C\xE1ch \u0111\u1EA1t m\u1EE5c ti\xEAu h\u1ED9 chi\u1EBFu?", options: ["B\u1EAFt khai \u0111\u1EC3 coach x\xE1c nh\u1EADn.", "D\xF9ng ca gi\u1EA3 \u0111\u1ECBnh, d\u1EEF ki\u1EC7n t\u1ED1i thi\u1EC3u, c\xE2u h\u1ECFi v\xE0 ng\u01B0\u1EDDi nh\u1EADn r\xF5.", "M\u01B0\u1EE3n h\u1ED3 s\u01A1 ng\u01B0\u1EDDi kh\xE1c kh\xF4ng xin ph\xE9p.", "B\u1ECF m\u1ECDi gi\u1EDBi h\u1EA1n v\xE0 ghi c\xE0ng nhi\u1EC1u c\xE0ng t\u1ED1t."], correct: 1, why: "B\xE0i \u0111\xE1nh gi\xE1 ph\u1ED1i h\u1EE3p v\xE0 l\u1EADp lu\u1EADn, kh\xF4ng ph\u1EE5 thu\u1ED9c vi\u1EC7c ti\u1EBFt l\u1ED9 th\xF4ng tin sinh s\u1EA3n c\u1EE7a c\xE1 nh\xE2n." },
    { objective: "privacy", section: "private-passport", prompt: "Khi h\u01B0\u1EDBng d\u1EABn ch\u0103m s\xF3c thay \u0111\u1ED5i, h\u1ED9 chi\u1EBFu c\u0169 n\xEAn \u0111\u01B0\u1EE3c d\xF9ng th\u1EBF n\xE0o?", options: ["Gi\u1EEF nh\u01B0 ch\u1EE9ng nh\u1EADn an to\xE0n v\u0129nh vi\u1EC5n.", "T\u1EF1 ch\u1ECDn ph\u1EA7n thu\u1EADn ti\u1EC7n v\xE0 b\u1ECF thu\u1ED1c.", "Coi nh\u1EADn x\xE9t coach thay ch\u1EC9 \u0111\u1ECBnh m\u1EDBi.", "C\u1EADp nh\u1EADt phi\xEAn b\u1EA3n v\xE0 c\xE2u h\u1ECFi v\u1EDBi ng\u01B0\u1EDDi ph\xF9 h\u1EE3p, gi\u1EEF l\u1ECBch s\u1EED v\xE0 quy\u1EC1n chia s\u1EBB."], correct: 3, why: "Phi\u1EBFu trao \u0111\u1ED5i c\u1EA7n ph\u1EA3n \xE1nh b\u1ED1i c\u1EA3nh m\u1EDBi; kh\xF4ng t\u1EF1 s\u1EEDa ch\u0103m s\xF3c ho\u1EB7c chuy\u1EC3n duy\u1EC7t c\u0169 th\xE0nh b\u1EA3o \u0111\u1EA3m m\u1EDBi." }
