  19: [
    { objective: "target", section: "observable-target", prompt: "M\xF4 t\u1EA3 n\xE0o \u0111\u1EE7 r\xF5 \u0111\u1EC3 \u0111\u1EBFm c\u01A1 h\u1ED9i h\xE0nh vi?", options: ["Tr\u01B0\u1EDBc m\u1ED7i ca \u0111\xE3 l\xEAn l\u1ECBch, x\xE1c nh\u1EADn ph\u01B0\u01A1ng \xE1n b\u1EEFa tr\u01B0a v\xE0 ghi c\xF3/kh\xF4ng/ch\u01B0a bi\u1EBFt.", "C\u1ED1 \u0103n l\xE0nh m\u1EA1nh h\u01A1n.", "Lu\xF4n k\u1EF7 lu\u1EADt.", "Kh\xF4ng bao gi\u1EDD th\xE8m m\xF3n kh\xE1c."], correct: 0, why: "T\xECnh hu\u1ED1ng, h\xE0nh \u0111\u1ED9ng v\xE0 d\u1EEF li\u1EC7u r\xF5 gi\xFAp ki\u1EC3m tra c\xE1ch th\u1EF1c hi\u1EC7n; kh\xF4ng thay b\u1EB1ng m\u1ED9t nh\xE3n t\xEDnh c\xE1ch." },
    { objective: "target", section: "observable-target", prompt: "Vi\u1EC7c g\u1EAFn v\u1EDBi hai ca m\u1ED7i tu\u1EA7n, trong b\u1ED1n tu\u1EA7n l\u1ECBch kh\xF4ng \u0111\u1ED5i. C\xF3 bao nhi\xEAu c\u01A1 h\u1ED9i d\u1EF1 ki\u1EBFn?", options: ["28 v\xEC tu\u1EA7n c\xF3 b\u1EA3y ng\xE0y.", "4 v\xEC c\xF3 b\u1ED1n tu\u1EA7n.", "8 c\u01A1 h\u1ED9i, ch\u01B0a bi\u1EBFt \u0111\xE3 th\u1EF1c hi\u1EC7n bao nhi\xEAu.", "2 v\xE0 ch\u1EAFc ch\u1EAFn th\xE0nh th\xF3i quen."], correct: 2, why: "2 \xD7 4 = 8 theo l\u1ECBch; c\u01A1 h\u1ED9i d\u1EF1 ki\u1EBFn kh\xF4ng ph\u1EA3i s\u1ED1 l\u1EA7n \u0111\xE3 l\xE0m hay b\u1EB1ng ch\u1EE9ng t\u1EF1 \u0111\u1ED9ng." },
    { objective: "barrier", section: "comb-context", prompt: "Ng\u01B0\u1EDDi bi\u1EBFt \u0111\u1ECDc nh\xE3n nh\u01B0ng c\u1EEDa h\xE0ng ph\xF9 h\u1EE3p qu\xE1 xa gi\u1EDD ngh\u1EC9. H\u1ED7 tr\u1EE3 n\xE0o kh\u1EDBp d\u1EEF ki\u1EC7n tr\u01B0\u1EDBc m\u1EAFt?", options: ["G\u1EEDi l\u1EA1i b\xE0i \u0111\u1ECDc nh\xE3n nh\u01B0 gi\u1EA3i ph\xE1p duy nh\u1EA5t.", "H\u1ECFi v\xE0 r\xE0 c\u01A1 h\u1ED9i mua/c\u1EA5t b\u1EEFa trong l\u1ECBch th\u1EF1c, kh\xF4ng quy thi\u1EBFu \xFD ch\xED.", "Ph\u1EA1t v\xEC ch\u01B0a ch\u1ECBu kh\xF3.", "B\u1EAFt b\u1ECF b\u1EEFa n\u1EBFu kh\xF4ng t\u1EDBi c\u1EEDa h\xE0ng."], correct: 1, why: "D\u1EEF ki\u1EC7n ch\u1EC9 ra r\xE0o c\u1EA3n c\u01A1 h\u1ED9i; v\u1EABn c\u1EA7n h\u1ECFi th\xEAm, kh\xF4ng ch\u1EA9n \u0111o\xE1n t\xEDnh c\xE1ch ho\u1EB7c \xE1p gi\u1EA3i ph\xE1p sai v\u1EA5n \u0111\u1EC1." },
    { objective: "barrier", section: "comb-context", prompt: "\u0110\u1ED9ng l\u1EF1c trong COM-B ch\u1EC9 l\xE0 m\u1EE5c ti\xEAu c\xF3 \xFD th\u1EE9c kh\xF4ng?", options: ["\u0110\xFAng, c\u1EA3m x\xFAc kh\xF4ng li\xEAn quan.", "\u0110\xFAng, c\u1EE9 c\xF3 m\u1EE5c ti\xEAu l\xE0 \u0111\u1EE7.", "\u0110\xFAng, ch\u1EC9 \u0111o qua s\u1ED1 ng\xE0y li\xEAn t\u1EE5c.", "Kh\xF4ng; c\xF2n qu\xE1 tr\xECnh t\u1EF1 \u0111\u1ED9ng v\xE0 c\u1EA3m x\xFAc, t\u01B0\u01A1ng t\xE1c v\u1EDBi n\u0103ng l\u1EF1c v\xE0 c\u01A1 h\u1ED9i."], correct: 3, why: "COM-B kh\xF4ng thu h\xE0nh vi v\xE0o \xFD ch\xED; c\xE1c th\xE0nh ph\u1EA7n t\u01B0\u01A1ng t\xE1c v\xE0 c\u1EA7n xem trong b\u1ED1i c\u1EA3nh c\u1EE5 th\u1EC3." },
    { objective: "plan", section: "cue-and-options", prompt: "K\u1EBF ho\u1EA1ch n\u1EBFu\u2013th\xEC n\xE0o gi\u1EEF nhi\u1EC7m v\u1EE5 v\xE0 an to\xE0n?", options: ["N\u1EBFu kh\xF4ng c\xF3 c\xE1ch gi\u1EEF b\u1EEFa l\u1EA1nh ph\xF9 h\u1EE3p, ch\u1ECDn ph\u01B0\u01A1ng \xE1n mua g\u1EA7n gi\u1EDD d\xF9ng \u0111\xE3 ki\u1EC3m tra.", "N\u1EBFu b\u1EADn, \u0111\u1EC3 m\xF3n d\u1EC5 h\u1ECFng ngo\xE0i n\xF3ng c\u1EA3 bu\u1ED5i.", "N\u1EBFu qu\xEAn, nh\u1ECBn b\xF9 h\xF4m sau.", "N\u1EBFu kh\xF3, b\u1ECF qua d\u1ECB \u1EE9ng \u0111\u1EC3 gi\u1EEF chu\u1ED7i."], correct: 0, why: "Ph\u01B0\u01A1ng \xE1n thay gi\u1EA3m tr\u1EDF ng\u1EA1i t\u1ED5 ch\u1EE9c m\xE0 kh\xF4ng h\u1EA1 \u0111i\u1EC1u ki\u1EC7n an to\xE0n ho\u1EB7c d\xF9ng b\xF9 tr\u1EEB." },
    { objective: "plan", section: "cue-and-options", prompt: "C\xF3 th\u1EC3 d\xF9ng b\u1ECF b\u1EEFa l\xE0m phi\xEAn b\u1EA3n t\u1ED1i thi\u1EC3u \u0111\u1EC3 gi\u1EEF \u0111i\u1EC3m ho\xE0n th\xE0nh kh\xF4ng?", options: ["C\xF3 v\xEC c\xE0ng \xEDt b\u01B0\u1EDBc c\xE0ng t\u1ED1t.", "C\xF3 n\u1EBFu kh\xF4ng b\xE1o coach.", "Kh\xF4ng; t\u1ED1i gi\u1EA3n c\xF4ng t\u1ED5 ch\u1EE9c, kh\xF4ng bi\u1EBFn thi\u1EBFu \u0103n ho\u1EB7c gi\u1EA3m an to\xE0n th\xE0nh th\xE0nh t\xEDch.", "C\xF3 v\xEC b\u1EA3ng m\u1EDBi l\xE0 m\u1EE5c ti\xEAu."], correct: 2, why: "Nhi\u1EC7m v\u1EE5 l\xE0 h\u1ED7 tr\u1EE3 b\u1EEFa d\xF9ng \u0111\u01B0\u1EE3c; kh\xF4ng d\xF9ng ch\u1EC9 s\u1ED1 h\u1ECDc t\u1EADp \u0111\u1EC3 khuy\u1EBFn kh\xEDch h\xE0nh vi c\xF3 h\u1EA1i.", safety: true },
    { objective: "review", section: "review-and-restart", prompt: "10 c\u01A1 h\u1ED9i, 6 c\xF3 d\u1EEF li\u1EC7u, 5 \u0111\xE3 l\xE0m. B\xE1o c\xE1o \u0111\xFAng l\xE0?", options: ["50% ch\u1EAFc ch\u1EAFn l\xE0 t\u1EF7 l\u1EC7 th\u1EF1c hi\u1EC7n th\u1EADt.", "83,3% trong d\u1EEF li\u1EC7u bi\u1EBFt, \u0111\u1ED9 ph\u1EE7 60%; b\u1ED1n l\u01B0\u1EE3t ch\u01B0a r\xF5.", "100% v\xEC b\u1ECF l\u1EA7n ch\u01B0a l\xE0m.", "83,3% v\xE0 ch\u1EAFc ch\u1EAFn th\xE0nh th\xF3i quen."], correct: 1, why: "5/6 \u2248 83,3%; 6/10 = 60%. D\u1EEF li\u1EC7u thi\u1EBFu kh\xF4ng t\u1EF1 l\xE0 th\u1EA5t b\u1EA1i ho\u1EB7c th\xE0nh c\xF4ng, t\u1EF7 l\u1EC7 kh\xF4ng \u0111o t\xEDnh t\u1EF1 \u0111\u1ED9ng." },
    { objective: "review", section: "review-and-restart", prompt: "Nh\u1EADt k\xFD l\xE0m ng\u01B0\u1EDDi h\u1ECDc t\u1ED9i l\u1ED7i v\xE0 mu\u1ED1n t\u1EADp b\xF9. B\u01B0\u1EDBc h\u1ED7 tr\u1EE3?", options: ["T\u0103ng gi\xE1m s\xE1t \u0111\u1EC3 b\u1EA3ng xanh.", "Khen b\xF9 tr\u1EEB l\xE0 k\u1EF7 lu\u1EADt.", "Ch\u1EDD \u0111\u1EE7 66 ng\xE0y m\u1EDBi s\u1EEDa.", "Kh\xF4ng b\xF9 tr\u1EEB; gi\u1EA3m/d\u1EEBng c\xE1ch theo d\xF5i g\xE2y h\u1EA1i, t\xECm h\u1ED7 tr\u1EE3 v\xE0 n\u1ED1i l\u1EA1i an to\xE0n khi ph\xF9 h\u1EE3p."], correct: 3, why: "Theo d\xF5i l\xE0 c\xF4ng c\u1EE5, kh\xF4ng m\u1EE5c ti\xEAu h\u01A1n s\u1EE9c kh\u1ECFe. Kh\xF4ng d\xF9ng m\u1ED1c h\xECnh th\xE0nh th\xF3i quen \u0111\u1EC3 tr\xEC ho\xE3n h\u1ED7 tr\u1EE3.", safety: true }
  ],
